-- Explicit academy-absorbed loss:expense against the actually booked disputed
-- asset. No new processor cash movement,customer-credit reduction or tax claim.
INSERT INTO public.capability_catalog(name,label,workspace,sensitive,scope_kinds)
 SELECT 'dispute-losses.view','View permitted disputed-payment loss records and sources',workspace,true,scope_kinds FROM public.capability_catalog WHERE name='receipts.view'
 UNION ALL SELECT 'dispute-losses.record','Request reviewed academy-absorbed disputed-payment losses',workspace,true,scope_kinds FROM public.capability_catalog WHERE name='receipts.edit';
-- No automatic role grants or machine-token ceiling changes.
CREATE TABLE public.provider_dispute_losses(
 academy_id uuid NOT NULL,id uuid NOT NULL,collection_id uuid NOT NULL,dispute_id text NOT NULL,disputed_account uuid NOT NULL,expense_account uuid NOT NULL,amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),posted_on date NOT NULL,source jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,collection_id,dispute_id),FOREIGN KEY(academy_id,collection_id) REFERENCES public.provider_collections(academy_id,id),FOREIGN KEY(academy_id,disputed_account) REFERENCES public.finance_accounts(academy_id,id),FOREIGN KEY(academy_id,expense_account) REFERENCES public.finance_accounts(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX provider_dispute_loss_window ON public.provider_dispute_losses(academy_id,posted_on,id);
ALTER TABLE public.provider_dispute_losses ENABLE ROW LEVEL SECURITY;ALTER TABLE public.provider_dispute_losses FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_boundary ON public.provider_dispute_losses USING(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid) WITH CHECK(academy_id=nullif(current_setting('app.academy_id',true),'')::uuid);
CREATE TRIGGER finance_book_write BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_losses FOR EACH STATEMENT EXECUTE FUNCTION public.guard_finance_book_write();
GRANT SELECT,INSERT ON public.provider_dispute_losses TO kavosh_runtime;
-- Preserve the old function identity while adding a private self-exclusion
-- needed to verify an INSERT's exact pre-loss proof at deferred completion.
DO $$ DECLARE d text;old text;replacement text;BEGIN
 d=pg_get_functiondef('public.provider_dispute_resolution_source(uuid,date)'::regprocedure);
 d=regexp_replace(d,'^CREATE OR REPLACE FUNCTION [^\n]+','CREATE OR REPLACE FUNCTION public.provider_dispute_resolution_basis(p_collection uuid,p_on date,p_exclude_loss uuid)');
 old=$q$SELECT value->>'disputeId' "disputeId",value->>'disputedAccountId' "accountId",value->>'accountingCurrencyId' "currencyId",value->>'accountingCurrencyCode' "currencyCode",(value->>'accountingUnitScale')::integer "unitScale",trunc(-sum((value->>'accountingGrossMinor')::numeric))::text "balanceMinor"
  FROM jsonb_array_elements(movement_rows) WHERE value->>'accountingGrossMinor' IS NOT NULL GROUP BY value->>'disputeId',value->>'disputedAccountId',value->>'accountingCurrencyId',value->>'accountingCurrencyCode',(value->>'accountingUnitScale')::integer$q$;
 replacement=$r$SELECT dispute_id "disputeId",account_id "accountId",currency_id "currencyId",currency_code "currencyCode",unit_scale "unitScale",trunc(sum(amount))::text "balanceMinor" FROM(
 SELECT value->>'disputeId' dispute_id,value->>'disputedAccountId' account_id,value->>'accountingCurrencyId' currency_id,value->>'accountingCurrencyCode' currency_code,(value->>'accountingUnitScale')::integer unit_scale,-(value->>'accountingGrossMinor')::numeric amount FROM jsonb_array_elements(movement_rows) WHERE value->>'accountingGrossMinor' IS NOT NULL
 UNION ALL SELECT l.dispute_id,l.disputed_account::text,l.source->>'currencyId',l.source->>'currencyCode',(l.source->>'unitScale')::integer,-l.amount_minor FROM public.provider_dispute_losses l WHERE l.academy_id=c.academy_id AND l.collection_id=c.id AND l.posted_on<=c.on_day AND(p_exclude_loss IS NULL OR l.id<>p_exclude_loss)
 ) asset_facts GROUP BY dispute_id,account_id,currency_id,currency_code,unit_scale$r$;
 IF strpos(d,old)=0 THEN RAISE EXCEPTION 'DISPUTE_LOSS_ASSET_BASE_CHANGED';END IF;d=replace(d,old,replacement);
 old=$q$ ) b;
 source=jsonb_build_object$q$;
 replacement=$r$ UNION ALL SELECT 'loss',l.id,to_jsonb(l) FROM public.provider_dispute_losses l WHERE l.academy_id=c.academy_id AND l.collection_id=c.id AND(p_exclude_loss IS NULL OR l.id<>p_exclude_loss)
 ) b;
 source=jsonb_build_object$r$;
 IF strpos(d,old)=0 THEN RAISE EXCEPTION 'DISPUTE_LOSS_BOOK_BASE_CHANGED';END IF;d=replace(d,old,replacement);
 old=$q$'cases',case_rows,'movements',movement_rows$q$;
 replacement=$r$'lossDispositions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',l.id,'disputeId',l.dispute_id,'postedOn',l.posted_on::text,'amountMinor',trunc(l.amount_minor)::text,'currencyId',l.source->'currencyId','currencyCode',l.source->'currencyCode','unitScale',l.source->'unitScale','disputedAccountId',l.disputed_account,'expenseAccountId',l.expense_account) ORDER BY l.id) FROM public.provider_dispute_losses l WHERE l.academy_id=c.academy_id AND l.collection_id=c.id AND l.posted_on<=c.on_day AND(p_exclude_loss IS NULL OR l.id<>p_exclude_loss)),'[]'::jsonb),'cases',case_rows,'movements',movement_rows$r$;
 IF strpos(d,old)=0 THEN RAISE EXCEPTION 'DISPUTE_LOSS_PROJECTION_BASE_CHANGED';END IF;EXECUTE replace(d,old,replacement);
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_resolution_basis(uuid,date,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_resolution_basis(uuid,date,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.provider_dispute_resolution_source(p_collection uuid,p_on date DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ SELECT public.provider_dispute_resolution_basis(p_collection,p_on,NULL) $$;
CREATE FUNCTION public.provider_dispute_loss_source(p_collection uuid,p_dispute text,p_on date,p_disputed uuid,p_expense uuid,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$
DECLARE c record;a record;e record;principal record;original jsonb;s jsonb;k jsonb;asset jsonb;amount numeric;factor numeric;debits numeric;returns numeric;booked uuid;BEGIN
 SELECT pc.*,cl.time_zone INTO c FROM public.provider_collections pc JOIN public.classes cl ON cl.academy_id=pc.academy_id AND cl.id=pc.class_id WHERE pc.id=p_collection;
 IF c.id IS NULL OR p_on IS NULL OR p_on<c.received_on OR p_on>(statement_timestamp() AT TIME ZONE c.time_zone)::date THEN RETURN NULL;END IF;
 SELECT * INTO principal FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND start_id=c.start_id ORDER BY received_at DESC,id DESC LIMIT 1;SELECT inspection INTO original FROM public.checkout_provider_inspections WHERE academy_id=c.academy_id AND id=c.inspection_id;
 IF principal.id IS NULL OR principal.object_conflict OR principal.inspection-ARRAY['state','disputed','paymentVerified'] IS DISTINCT FROM original-ARRAY['state','disputed','paymentVerified'] OR(principal.inspection->>'state'='captured' OR principal.inspection->>'state'='requires_review' AND principal.inspection->'disputed'='true'::jsonb) IS DISTINCT FROM true THEN RETURN NULL;END IF;
 s=public.provider_dispute_resolution_basis(c.id,p_on,p_exclude);IF s IS NULL OR s ? 'unavailable' OR s->'onIsFuture' IS DISTINCT FROM 'false'::jsonb OR s->'pageChainComplete' IS DISTINCT FROM 'true'::jsonb OR s->'pageChainConflict' IS DISTINCT FROM 'false'::jsonb OR s->'disputeAttentionRetained' IS DISTINCT FROM 'true'::jsonb THEN RETURN NULL;END IF;
 SELECT value INTO k FROM jsonb_array_elements(s->'cases') WHERE value->>'disputeId'=p_dispute;
 IF k IS NULL OR k->>'status' IS DISTINCT FROM 'lost' OR k->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR k->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR k->'exceedsOriginalAmount' IS DISTINCT FROM 'false'::jsonb OR k->>'providerUnitScale' IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=p_dispute) OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=p_dispute AND(m->'observed' IS DISTINCT FROM 'true'::jsonb OR m->'recognized' IS DISTINCT FROM 'true'::jsonb OR m->'ownershipConflict' IS DISTINCT FROM 'false'::jsonb OR m->'requiresFxReview' IS DISTINCT FROM 'false'::jsonb OR m->'amountMatched' IS DISTINCT FROM 'true'::jsonb OR m->'accountingMatchesLatest' IS DISTINCT FROM 'true'::jsonb OR m->'futureDatedAccounting' IS DISTINCT FROM 'false'::jsonb OR m->>'postingId' IS NULL OR m->'currencyCode' IS DISTINCT FROM k->'currencyCode' OR m->'providerUnitScale' IS DISTINCT FROM k->'providerUnitScale')) THEN RETURN NULL;END IF;
 SELECT * INTO a FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=p_disputed;SELECT * INTO e FROM public.finance_account_catalogue WHERE academy_id=c.academy_id AND id=p_expense;
 IF a.id IS NULL OR e.id IS NULL OR a.id=e.id OR NOT a.active OR NOT e.active OR a.kind<>'asset' OR a.normal_balance<>'debit' OR a.operational_role<>'other' OR e.kind<>'expense' OR e.operational_role<>'expense' OR a.currency_id<>e.currency_id OR a.unit_scale<>e.unit_scale OR a.currency_code IS DISTINCT FROM k->>'currencyCode' OR(a.hub_id IS NOT NULL AND a.hub_id<>c.hub_id) OR(e.hub_id IS NOT NULL AND e.hub_id<>c.hub_id) THEN RETURN NULL;END IF;
 IF(SELECT count(*) FROM jsonb_array_elements(s->'disputedAssets') x WHERE x->>'disputeId'=p_dispute AND(x->>'balanceMinor')::numeric<>0)<>1 THEN RETURN NULL;END IF;
 SELECT value INTO asset FROM jsonb_array_elements(s->'disputedAssets') WHERE value->>'disputeId'=p_dispute AND value->>'accountId'=a.id::text AND value->>'currencyId'=a.currency_id::text AND(value->>'unitScale')::integer=a.unit_scale;
 amount=(asset->>'balanceMinor')::numeric;factor=power(10::numeric,a.unit_scale)/power(10::numeric,(k->>'providerUnitScale')::integer);
 SELECT coalesce(sum(-(m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric<0),0),coalesce(sum((m->>'grossMinor')::numeric) FILTER(WHERE(m->>'grossMinor')::numeric>0),0) INTO debits,returns FROM jsonb_array_elements(s->'movements') m WHERE m->>'disputeId'=p_dispute;
 IF amount IS NULL OR amount<=0 OR amount>=1e38 OR amount<>trunc(amount) OR debits<>(k->>'amountMinor')::numeric OR returns>debits OR amount<>(debits-returns)*factor THEN RETURN NULL;END IF;
 SELECT id INTO booked FROM public.provider_dispute_losses WHERE academy_id=c.academy_id AND collection_id=c.id AND dispute_id=p_dispute AND(p_exclude IS NULL OR id<>p_exclude);IF booked IS NOT NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('collectionId',c.id,'disputeId',p_dispute,'hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id,'collectorId',c.collector_id,'holdingAccountId',c.holding_account,'accountId',c.account_id,'sourceStamp',s->'sourceFingerprint','postedOn',p_on::text,'disputedAccountId',a.id,'disputedVersion',a.version,'expenseAccountId',e.id,'expenseVersion',e.version,'currencyId',a.currency_id,'currencyCode',a.currency_code,'unitScale',a.unit_scale,'amountMinor',trunc(amount)::text,'disposition','academy_expense','taxTreatment','not_claimed','lines',jsonb_build_array(jsonb_build_object('accountId',e.id,'accountVersion',e.version,'side','debit','amountMinor',trunc(amount)::text),jsonb_build_object('accountId',a.id,'accountVersion',a.version,'side','credit','amountMinor',trunc(amount)::text)));
END $$;
CREATE FUNCTION public.guard_provider_dispute_loss() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE c record;p record;s jsonb;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_IMMUTABLE' USING ERRCODE='23514';END IF;
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=NEW.collection_id;PERFORM public.lock_customer_credit(c.id);PERFORM public.lock_collector_funds(c.collector_id,c.holding_account);PERFORM id FROM public.tuition_invoices WHERE academy_id=NEW.academy_id AND id=c.invoice_id FOR UPDATE;PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':checkout-provider:'||c.account_id,0));
 s=public.provider_dispute_loss_source(c.id,NEW.dispute_id,NEW.posted_on,NEW.disputed_account,NEW.expense_account);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF s IS NULL OR NEW.source IS DISTINCT FROM s OR NEW.amount_minor IS DISTINCT FROM(s->>'amountMinor')::numeric OR p.id IS NULL OR p.action IS DISTINCT FROM 'finance.provider-dispute.loss' OR p.status IS DISTINCT FROM 'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version<>0 OR p.privacy_capability IS DISTINCT FROM 'dispute-losses.view' OR p.review_context->'source' IS DISTINCT FROM s
 OR p.payload IS DISTINCT FROM jsonb_build_object('collectionId',NEW.collection_id,'disputeId',NEW.dispute_id,'sourceStamp',s->'sourceStamp','disputedFundsAccount',jsonb_build_object('id',NEW.disputed_account,'version',s->'disputedVersion'),'expenseAccount',jsonb_build_object('id',NEW.expense_account,'version',s->'expenseVersion'),'postedOn',NEW.posted_on::text,'period',p.payload->'period','disposition','academy_expense','taxTreatment','not_claimed','reason',NEW.reason)
 OR p.scope->'recordContext' IS DISTINCT FROM jsonb_build_object('hubId',c.hub_id,'classId',c.class_id,'studentId',c.student_id) OR NOT public.report_comment_human_verified(NEW.created_by) OR NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND status='active') THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) AND(p.requester_id=NEW.created_by OR NOT public.is_supervisor(NEW.created_by,p.requester_id) OR c.student_id=NEW.created_by OR EXISTS(SELECT 1 FROM public.family_relationships WHERE academy_id=NEW.academy_id AND student_id=c.student_id AND guardian_id=NEW.created_by) OR EXISTS(SELECT 1 FROM public.finance_collectors WHERE academy_id=NEW.academy_id AND id=c.collector_id AND person_id=NEW.created_by)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_UPPER_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_loss BEFORE INSERT OR UPDATE OR DELETE ON public.provider_dispute_losses FOR EACH ROW EXECUTE FUNCTION public.guard_provider_dispute_loss();
CREATE FUNCTION public.complete_provider_dispute_loss() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog SET DateStyle='ISO,YMD' AS $$ DECLARE p record;j record;actual jsonb;BEGIN
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',account_version,'side',side,'amountMinor',trunc(amount_minor)::text) ORDER BY line_number) INTO actual FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id;
 IF NEW.source IS DISTINCT FROM public.provider_dispute_loss_source(NEW.collection_id,NEW.dispute_id,NEW.posted_on,NEW.disputed_account,NEW.expense_account,NEW.id) OR p.status IS DISTINCT FROM 'applied' OR p.reviewer_id IS DISTINCT FROM NEW.created_by OR j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.reverses_id IS NOT NULL OR j.line_count<>2 OR actual IS DISTINCT FROM NEW.source->'lines' OR j.reference IS DISTINCT FROM 'provider-dispute-loss:'||NEW.id::text OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer
 OR NOT EXISTS(SELECT 1 FROM public.audit_events WHERE academy_id=NEW.academy_id AND entity_id=NEW.id AND actor_id=NEW.created_by AND created_at=transaction_timestamp() AND action='finance.provider-dispute.loss-recorded' AND changes=jsonb_build_object('approvalId',NEW.approval_id,'collectionId',NEW.collection_id,'severity','critical','disposition','academy_expense','customerCreditChanged',false,'providerOperationPerformed',false)) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_INCOMPLETE' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_loss_complete AFTER INSERT ON public.provider_dispute_losses DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.complete_provider_dispute_loss();
CREATE FUNCTION public.provider_dispute_loss_effect() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.action='finance.provider-dispute.loss' AND NEW.status='applied' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER provider_dispute_loss_effect AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_loss_effect();
CREATE FUNCTION public.provider_dispute_loss_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;hubs uuid[];bindings jsonb;BEGIN
 SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'collectionId')::uuid;
 SELECT coalesce(jsonb_agg(DISTINCT b.value),'[]'::jsonb) INTO bindings FROM public.approval_requests p CROSS JOIN LATERAL jsonb_array_elements(p.privacy_bindings) b WHERE p.academy_id=NEW.academy_id AND(p.id IN(SELECT approval_id FROM public.provider_dispute_postings WHERE academy_id=NEW.academy_id AND collection_id=c.id) OR p.id IN(SELECT x.approval_id FROM public.provider_dispute_corrections x JOIN public.provider_dispute_postings d ON d.academy_id=x.academy_id AND d.id=x.posting_id WHERE d.academy_id=NEW.academy_id AND d.collection_id=c.id));
 IF jsonb_array_length(bindings)>50 THEN RAISE EXCEPTION 'DISPUTE_LOSS_PRIVACY_REQUIRES_BACKGROUND' USING ERRCODE='23514';END IF;
 SELECT array_agg(hub_id ORDER BY id) INTO hubs FROM public.finance_accounts WHERE academy_id=NEW.academy_id AND id IN(c.credit_account,c.holding_account,(NEW.payload#>>'{disputedFundsAccount,id}')::uuid,(NEW.payload#>>'{expenseAccount,id}')::uuid);
 NEW.privacy_bindings=NEW.privacy_bindings||bindings||jsonb_build_array(jsonb_build_object('capability','receipts.view','scope',NEW.scope),jsonb_build_object('capability','checkouts.view','scope',NEW.scope),jsonb_build_object('capability','invoices.view','scope',NEW.scope),jsonb_build_object('capability','expenses.view','scope',NEW.scope),public.approval_hub_binding('accounts.view',hubs),public.approval_hub_binding('journals.view',hubs));RETURN NEW;
END $$;
CREATE TRIGGER zz_provider_dispute_loss_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action='finance.provider-dispute.loss') EXECUTE FUNCTION public.provider_dispute_loss_privacy();
CREATE FUNCTION public.provider_dispute_loss_journal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.reverses_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_CORRECTION_REQUIRED' USING ERRCODE='23514';END IF;
 IF public.provider_transaction_reference(NEW.reference) LIKE 'provider-dispute-loss:%' AND NOT EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=NEW.academy_id AND id=NEW.id AND approval_id=NEW.approval_id AND public.provider_transaction_reference(NEW.reference)='provider-dispute-loss:'||id::text) THEN RAISE EXCEPTION 'PROVIDER_DISPUTE_LOSS_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER provider_dispute_loss_journal BEFORE INSERT ON public.finance_journals FOR EACH ROW EXECUTE FUNCTION public.provider_dispute_loss_journal_guard();
-- A later return after an absorbed loss needs reviewed recovery accounting,
-- not automatic reuse of the returned-principal release or a mapping rewrite.
DO $$ DECLARE d text;needle text;BEGIN
 d=pg_get_functiondef('public.provider_dispute_release_basis(uuid,date)'::regprocedure);needle='s=public.provider_dispute_resolution_source(c.id,p_on);';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_LOSS_RELEASE_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'IF EXISTS(SELECT 1 FROM public.provider_dispute_losses WHERE academy_id=c.academy_id AND collection_id=c.id) THEN RETURN jsonb_build_object(''eligible'',false,''code'',''DISPUTE_LOSS_RESOLUTION_REVIEW_REQUIRED'');END IF;'||needle);
 d=pg_get_functiondef('public.provider_dispute_correction_source(uuid,uuid,date,uuid,uuid,uuid,uuid)'::regprocedure);needle='BEGIN';IF strpos(d,needle)=0 THEN RAISE EXCEPTION 'DISPUTE_LOSS_CORRECTION_BASE_CHANGED';END IF;EXECUTE replace(d,needle,'BEGIN IF EXISTS(SELECT 1 FROM public.provider_dispute_losses l JOIN public.provider_dispute_postings d ON d.academy_id=l.academy_id AND d.collection_id=l.collection_id AND d.dispute_id=l.dispute_id WHERE d.id=p_posting) THEN RETURN NULL;END IF;');
 d=pg_get_viewdef('public.provider_cost_events'::regclass,true);EXECUTE 'CREATE OR REPLACE VIEW public.provider_cost_events WITH(security_invoker=true) AS '||rtrim(d,E';\n ')||' UNION ALL SELECT academy_id,id,collection_id,approval_id,posted_on,amount_minor,source FROM public.provider_dispute_losses';
END $$;
REVOKE ALL ON FUNCTION public.provider_dispute_loss_source(uuid,text,date,uuid,uuid,uuid),public.guard_provider_dispute_loss(),public.complete_provider_dispute_loss(),public.provider_dispute_loss_effect(),public.provider_dispute_loss_privacy(),public.provider_dispute_loss_journal_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_dispute_loss_source(uuid,text,date,uuid,uuid,uuid) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 335 $$;
